import{_ as a,o as r,c as i,aO as n}from"./chunks/framework.BFrk9dwu.js";const o="/travel/kunming.jpg",e="/travel/kunming/d1-cuihu-1.jpg",l="/travel/kunming/half-jiangwutang.jpg",s="/travel/kunming/half-laojie.jpg",g="/travel/kunming/half-jinmabiji.jpg",d="/travel/kunming/half-night-1.jpg",c="/travel/kunming/d1-haigeng-1.jpg",p="/travel/kunming/d2-museum-1.jpg",h="/travel/kunming/d2-dounan-1.jpg",x=JSON.parse('{"title":"昆明：滇池与老街的一天半","description":"昆明一天半怎么玩：半天逛翠湖、讲武堂、昆明老街、金马碧鸡坊和夜市，第二天滇池看红嘴鸥、云南省博物馆、傍晚斗南花市","frontmatter":{"title":"昆明：滇池与老街的一天半","date":"2026-11-17T18:50:00.000Z","description":"昆明一天半怎么玩：半天逛翠湖、讲武堂、昆明老街、金马碧鸡坊和夜市，第二天滇池看红嘴鸥、云南省博物馆、傍晚斗南花市","categories":["life","travel"],"permalink":"/pages/fc03a9"},"headers":[],"relativePath":"life/travel/kunming.md","filePath":"life/travel/kunming.md","lastUpdated":1794900913000}'),u={name:"life/travel/kunming.md"};function f(m,t,_,v,b,k){return r(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="昆明-滇池与老街的一天半" tabindex="-1">昆明：滇池与老街的一天半 <a class="header-anchor" href="#昆明-滇池与老街的一天半" aria-label="Permalink to &quot;昆明：滇池与老街的一天半&quot;">​</a></h1><div class="travel-hero"><img src="'+o+'" alt="傍晚的金马碧鸡坊：牌坊被夕光染成金色，背后是成片的高楼"></div><p>昆明当中转站刚好。半天给老城，一天给滇池和博物馆，傍晚顺手去斗南抱一束花上高铁——赶不上海鸥也没关系，这条线一年四季都走得通。</p><h2 id="什么时候去" tabindex="-1">什么时候去 <a class="header-anchor" href="#什么时候去" aria-label="Permalink to &quot;什么时候去&quot;">​</a></h2><ul><li><strong>11 月–次年 3 月</strong>：红嘴鸥在滇池和翠湖过冬，最热闹。</li><li><strong>3–5 月</strong>：气候最舒服，花开得早。</li><li><strong>6–10 月</strong>：雨季，下午容易下雨，但菌子上市，值得为吃来一趟。</li></ul><h2 id="怎么到" tabindex="-1">怎么到 <a class="header-anchor" href="#怎么到" aria-label="Permalink to &quot;怎么到&quot;">​</a></h2><ul><li>直飞昆明长水机场，两个半小时左右。</li><li>机场坐地铁 6 号线进城，四十分钟到塘子巷，换乘 2 号线去哪都方便。</li><li>昆明站在市区，昆明南站在呈贡（高铁去大理、丽江多在南站发车，提前看好票面）。</li></ul><h2 id="一天半怎么走" tabindex="-1">一天半怎么走 <a class="header-anchor" href="#一天半怎么走" aria-label="Permalink to &quot;一天半怎么走&quot;">​</a></h2><h3 id="半天-·-翠湖、讲武堂和老街" tabindex="-1">半天 · 翠湖、讲武堂和老街 <a class="header-anchor" href="#半天-·-翠湖、讲武堂和老街" aria-label="Permalink to &quot;半天 · 翠湖、讲武堂和老街&quot;">​</a></h3><p>下午先去<strong>翠湖公园</strong>。免费，冬天湖面上停着海鸥，从湖心亭、九曲桥绕一圈，一小时够。湖西岸就是<strong>云南陆军讲武堂</strong>——土黄色的法式两层小楼加一片空操场，免费进去看，走一圈二十分钟；遇上换岗仪式还挺有意思，去之前查一下当天的开放时间。</p><div class="travel-grid"><figure><img src="'+e+'" alt="翠湖公园：湖面停着一群红嘴鸥，岸边垂柳和石桥，老人坐在长椅上喂鸥"><figcaption>翠湖，冬天湖面上全是海鸥</figcaption></figure><figure><img src="'+l+'" alt="云南陆军讲武堂：土黄色法式主楼与拱门，楼前一片空旷操场"><figcaption>讲武堂就在翠湖西岸，一墙之隔</figcaption></figure></div><p>从翠湖往南走十几分钟就是<strong>昆明老街</strong>：光华街、文明街、钱王街一带，两层的老铺面，木格子窗，早上是本地人买花买茶，傍晚摊子才真正热闹起来。</p><p>再往南走到<strong>金马碧鸡坊</strong>，两座牌坊隔着马路对着站。白天看结构，亮灯之后才是它的样子——路口车流拉成光带，是昆明最出片的一个机位。</p><div class="travel-grid"><figure><img src="'+s+'" alt="昆明老街：两层砖木老铺面，摊主在门口炸油条，晨光斜照石板路"><figcaption>老街的早上，油条刚下锅</figcaption></figure><figure><img src="'+g+'" alt="金马碧鸡坊夜景：两座金碧辉煌的牌坊相对而立，车灯拉成光带"><figcaption>金马碧鸡坊，晚上亮灯才好看</figcaption></figure></div><p><strong>晚上去夜市。</strong> 就近的<strong>南强街巷</strong>，老院子改的街区，头顶一串串灯，小吃摊和咖啡店挤在一起，逛吃到十点都有人。想吃正经菜就往祥云街、三合营那边走，是本地人吃饭的地方。</p><figure class="travel-photo"><img src="'+d+'" alt="南强街巷夜市：老院子改造的街区，头顶串灯和红灯笼，两侧小吃摊与咖啡店"><figcaption>南强街巷，灯一亮人就多起来</figcaption></figure><h3 id="第二天-·-滇池、省博和斗南" tabindex="-1">第二天 · 滇池、省博和斗南 <a class="header-anchor" href="#第二天-·-滇池、省博和斗南" aria-label="Permalink to &quot;第二天 · 滇池、省博和斗南&quot;">​</a></h3><p><strong>上午去滇池。</strong> 七点半到<strong>海埂大坝</strong>，红嘴鸥一群一群贴着你飞，鸥粮在坝上就有卖。沿滇池边走一段，远看西山睡美人。周末人多，早点去，停车位也紧张。</p><figure class="travel-photo"><img src="'+c+'" alt="海埂大坝：成群红嘴鸥在低空盘旋，游客伸手喂鸥粮，滇池开阔"><figcaption>海埂大坝，鸥群贴着栏杆飞</figcaption></figure><p>看完可以顺路去<strong>海埂公园</strong>，或者坐索道过湖上西山（看天气，风大就停运）。</p><p><strong>下午去云南省博物馆。</strong> 在广福路，免费，提前在公众号预约，<strong>周一闭馆</strong>。重点看古滇国青铜器，牛虎铜案就在那儿；顺便把云南从石器时代到近代的时间线走一遍，一个下午刚好。馆里冷气足，走累了正好歇脚。</p><figure class="travel-photo"><img src="'+p+'" alt="云南省博物馆：深红色方形体块的新馆，立面有竖向凹槽肌理，前方是石材广场"><figcaption>省博新馆，一个下午刚好走完</figcaption></figure><p><strong>傍晚去斗南花市。</strong> 地铁 4 号线到斗南站，出站走十分钟。白天是零售，晚上八点以后才是批发场——成捆的玫瑰按把卖，价格不像真的。买一束带上高铁也不麻烦。</p><figure class="travel-photo"><img src="'+h+'" alt="斗南花市大棚：成捆的玫瑰和绣球堆在桶里，花农抱着花走过通道"><figcaption>斗南的批发场，花的价钱不像真的</figcaption></figure><p>逛完斗南直接回市区住，也可以从斗南打车去昆明南站，高铁两小时到大理，再两小时到丽江。</p><h2 id="住哪" tabindex="-1">住哪 <a class="header-anchor" href="#住哪" aria-label="Permalink to &quot;住哪&quot;">​</a></h2><ul><li><strong>翠湖、文林街一带</strong>：走路就能逛翠湖和讲武堂，安静，咖啡馆多。</li><li><strong>南屏街、金马碧鸡坊附近</strong>：地铁方便，晚上逛老街和南强街巷都在步行范围，吵一点。</li></ul><h2 id="吃什么" tabindex="-1">吃什么 <a class="header-anchor" href="#吃什么" aria-label="Permalink to &quot;吃什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>吃的</th><th>说明</th></tr></thead><tbody><tr><td>过桥米线</td><td>汤要先烫熟肉片，别一股脑全倒进去</td></tr><tr><td>豆花米线</td><td>凉拌的，酸辣，早饭合适</td></tr><tr><td>烧饵块</td><td>抹酱夹油条，路边摊最香</td></tr><tr><td>汽锅鸡</td><td>不放水，全靠蒸汽凝汤</td></tr><tr><td>鲜花饼</td><td>现烤的才好吃，凉了差很多</td></tr><tr><td>菌子火锅</td><td>六到十月才有，一定煮熟再吃</td></tr></tbody></table><h2 id="避坑" tabindex="-1">避坑 <a class="header-anchor" href="#避坑" aria-label="Permalink to &quot;避坑&quot;">​</a></h2><ul><li><strong>讲武堂、省博的闭馆日先查</strong>：博物馆多是周一闭馆，讲武堂遇到检修还会临时关，出门前看一眼公众号。</li><li><strong>喂海鸥别用面包</strong>：买专用的鸥粮，面包对它们不好，也不耐饿。</li><li><strong>海埂大坝停车</strong>：旺季一位难求，打车或地铁加公交更省事。</li><li><strong>省博预约</strong>：周末名额放得快，提前一天约，现场排队占时间。</li><li><strong>斗南别只逛白天</strong>：白天是零售价，晚上八点后的批发场才是它本来的样子，但要留意返程地铁末班。</li></ul><h2 id="花费参考-淡季" tabindex="-1">花费参考 | 淡季 <a class="header-anchor" href="#花费参考-淡季" aria-label="Permalink to &quot;花费参考 | 淡季&quot;">​</a></h2><p>一天半不含大交通，人均 60：住宿 60 一晚，翠湖、讲武堂、省博、海埂大坝都不收门票，吃一天七八十，斗南买花看手气。价格年年变，出门前自己再核一遍。</p><p><a href="/life/travel/">← 回旅游攻略</a></p>',34)])])}const P=a(u,[["render",f]]);export{x as __pageData,P as default};
